<?php
require_once __DIR__.'/includes/functions.php';
$pageTitle='Explore cars — DriveEase';
$q=trim($_GET['q']??''); $trans=trim($_GET['transmission']??''); $max=trim($_GET['max_rate']??'');
$sql="SELECT * FROM cars WHERE status='available'"; $params=[];
if($q!==''){ $sql.=" AND (name LIKE ? OR model LIKE ? OR color LIKE ?)"; $like='%'.$q.'%'; array_push($params,$like,$like,$like); }
if(in_array($trans,['Automatic','Manual'],true)){ $sql.=' AND transmission=?'; $params[]=$trans; }
if($max!=='' && is_numeric($max) && (float)$max>=0){$sql.=' AND rate_per_day<=?';$params[]=(float)$max;}
$sql.=' ORDER BY rate_per_day ASC'; $stmt=db()->prepare($sql);$stmt->execute($params);$cars=$stmt->fetchAll();
require __DIR__.'/includes/header.php'; ?>
<section class="page-hero"><div class="container"><span class="eyebrow">THE DRIVE AWAITS</span><h1>Explore the <span class="text-gradient">fleet.</span></h1><p>Find the right car for your next plan, from everyday drives to weekend escapes.</p></div></section>
<section class="section"><div class="container"><form class="filter-bar" method="get"><label class="search-field"><span>⌕</span><input type="search" name="q" placeholder="Search make, model or color" value="<?= e($q) ?>"></label><select name="transmission" aria-label="Transmission"><option value="">Any transmission</option><option <?= $trans==='Automatic'?'selected':'' ?>>Automatic</option><option <?= $trans==='Manual'?'selected':'' ?>>Manual</option></select><label class="rate-field"><span>Max daily rate</span><input type="number" min="0" name="max_rate" placeholder="Any" value="<?= e($max) ?>"></label><button class="btn btn-primary" type="submit">Apply filters</button><a class="btn btn-ghost" href="<?= e(url('cars.php')) ?>">Reset</a></form><div class="results-meta"><span><?= count($cars) ?> car<?= count($cars)!==1?'s':'' ?> available</span><span>Rates shown in PKR per day</span></div><div class="car-grid"><?php foreach($cars as $car): ?><article class="car-card"><div class="car-photo"><?php if($car['image_url']): ?><img src="<?= e($car['image_url']) ?>" alt="<?= e($car['name']) ?>"><?php else: ?><div class="car-placeholder">🚘</div><?php endif; ?><span class="car-tag">Available</span></div><div class="car-card-body"><div class="car-title-row"><div><h3><?= e($car['name']) ?></h3><p><?= e($car['model']) ?> · <?= e($car['color']) ?></p></div><div class="car-price"><?= money($car['rate_per_day']) ?><small>/ day</small></div></div><div class="car-specs"><span>◉ <?= e($car['transmission']) ?></span><span>♧ <?= (int)$car['seats'] ?> seats</span><span>⌁ <?= e($car['registration_no']) ?></span></div><a class="btn btn-outline btn-block" href="<?= e(url('car.php?id='.(int)$car['id'])) ?>">View details ↗</a></div></article><?php endforeach; ?></div><?php if(!$cars): ?><div class="empty-state"><div class="empty-icon">⌕</div><h3>No matching cars</h3><p>Try changing your search or removing a filter.</p><a class="btn btn-primary" href="<?= e(url('cars.php')) ?>">Clear filters</a></div><?php endif; ?></div></section>
